package org.sleepwell.app;
import android.content.*;import java.io.*;import java.util.*;import java.util.function.BooleanSupplier;
/** Shared manual/automatic whole-library save. Runs off-main and retains the lease through provider cleanup. */
final class CloudAudioSave {
 static final class Result {final CloudAudioVersions.Entry entry;final boolean attempted,verified,cleanup;final String message,error;Result(CloudAudioVersions.Entry entry,boolean attempted,boolean verified,boolean cleanup,String message,String error){this.entry=entry;this.attempted=attempted;this.verified=verified;this.cleanup=cleanup;this.message=message;this.error=error;}}
 final Context app;final Records.Factory records;final CloudAudioVersions.Factory preferences;final CloudBackupSettings.Factory destinations;private volatile CloudBackupProvider provider;private volatile boolean cancelled;private boolean cleanupConfirmed=true;
 CloudAudioSave(Context app,Records.Factory records,CloudAudioVersions.Factory preferences,CloudBackupSettings.Factory destinations){this.app=app.getApplicationContext();this.records=records;this.preferences=preferences;this.destinations=destinations;}
 private boolean scope(){return records==Records.PRODUCTION||preferences!=CloudAudioVersions.PRODUCTION&&destinations!=CloudBackupSettings.PRODUCTION;}
 Result save(LibraryAudioArchive.Plan plan,CloudBackupSettings.Destination destination,String version,BooleanSupplier allowed){return save(plan,destination,version,allowed,()->{});}
 Result save(LibraryAudioArchive.Plan plan,CloudBackupSettings.Destination destination,String version,BooleanSupplier allowed,Runnable beforeCreate){try{return owned(plan,destination,version,allowed,beforeCreate);}catch(Exception failure){String issue=CloudAudioJob.notice(failure);return new Result(null,false,false,cleanupConfirmed,issue,issue);}}
 private Result owned(LibraryAudioArchive.Plan plan,CloudBackupSettings.Destination destination,String version,BooleanSupplier allowed,Runnable beforeCreate)throws Exception{Object lease=new Object();boolean acquired=false,creationAttempted=false;cleanupConfirmed=true;CloudAudioVersions.Entry entry=null;File staged=null;String error="",warning="";boolean verified=false;List<CloudAudioVersions.Entry> history=List.of();SharedPreferences prefs=preferences.open(app),destinationPrefs=destinations.preferences(app);BooleanSupplier active=()->!cancelled&&AutoCloudAudio.historyAllowed()&&allowed.getAsBoolean()&&CloudBackupSettings.current(destinationPrefs,destination);
        try{if(!scope())throw new IOException("Private destination scope changed.");if(!CloudBackupProvider.granted(app.getContentResolver(),android.net.Uri.parse(destination.tree)))throw new IOException("Folder access expired. Choose the destination again before saving audio.");NightAudioArchive.active(active);if(!CloudBackupLease.acquire(lease))throw new IOException("Another folder backup is still finishing. Wait, then review and save again.");acquired=true;entry=new CloudAudioVersions.Entry(version,destination,plan);CloudAudioVersions.record(prefs,entry);
            try(Store store=records.open(app);LibraryAudioArchive.Snapshot immutable=LibraryAudioArchive.stage(app,store,plan,active)){staged=CloudAudioDocuments.fresh(app,"cloud-audio-save-");try(OutputStream output=bounded(new FileOutputStream(staged),LibraryAudioImport.MAX_ZIP)){immutable.write(output,active);}}long size=staged.length();if(size<=0||size>LibraryAudioImport.MAX_ZIP)throw new IOException("The complete ZIP exceeds the supported size. Nothing was omitted.");String expected;try(InputStream input=new FileInputStream(staged)){expected=CloudAudioDocuments.copy(input,null,LibraryAudioImport.MAX_ZIP,active);}NightAudioArchive.active(active);
            CloudBackupProvider selected=new CloudBackupProvider(app,destination.tree);provider=selected;entry=entry.next("CREATING","Creating one new ZIP version. A partial file may remain if interrupted.","",size,expected);CloudAudioVersions.record(prefs,entry);NightAudioArchive.active(active);beforeCreate.run();NightAudioArchive.active(active);creationAttempted=true;CloudBackupCopy.Document document=selected.create(entry.name,"application/zip");entry=entry.next("WRITING","Writing the complete private snapshot…",document.uri,size,expected);CloudAudioVersions.record(prefs,entry);NightAudioArchive.active(active);
            OutputStream output=null;try{output=selected.output(document);try(InputStream input=new FileInputStream(staged)){String sent=CloudAudioDocuments.copy(input,output,size,active);if(!sent.equals(expected))throw new IOException("The private ZIP changed before upload finished.");}output.flush();}finally{closeProvider(output);}NightAudioArchive.active(active);entry=entry.next("VERIFYING","Reading provider bytes back and checking SHA-256…",document.uri,size,expected);CloudAudioVersions.record(prefs,entry);
            InputStream input=null;String actual;long[] read={0};try{input=selected.input(document);InputStream counted=new FilterInputStream(input){public int read(byte[] bytes,int off,int length)throws IOException{int n=in.read(bytes,off,length);if(n>0)read[0]+=n;return n;}public int read()throws IOException{int n=in.read();if(n>=0)read[0]++;return n;}};actual=CloudAudioDocuments.copy(counted,null,size,active);}finally{closeProvider(input);}NightAudioArchive.active(active);if(read[0]!=size||!actual.equals(expected))throw new IOException("Provider read-back differs from the staged ZIP. This version is unverified.");entry=entry.next("VERIFIED","Provider read-back verified. Your storage app controls remote upload.",document.uri,size,expected);CloudAudioVersions.record(prefs,entry);verified=true;
        }catch(Exception failure){error=CloudAudioJob.notice(failure);if(entry!=null){String status=!cleanupConfirmed?"CLEANUP":creationAttempted?"UNCERTAIN":cancelled?"CANCELLED":"ERROR";String message=!cleanupConfirmed?"Provider stream cleanup could not be confirmed. Further folder backups stay blocked until the process restarts.":creationAttempted?"A complete or partial file may exist. It is not verified; existing versions were kept. "+error:cancelled?"Cancelled before provider creation. Existing versions were kept.":error;entry=entry.next(status,message,entry.uri,entry.zipBytes,entry.sha);try{CloudAudioVersions.record(prefs,entry);}catch(Exception receiptFailure){error+=" The local receipt could not be updated; review the provider folder before any new save.";}}}
        finally{provider=null;if(staged!=null)try{CloudAudioDocuments.remove(staged);}catch(IOException cleanup){warning=" Private ZIP staging still needs cleanup.";}if(acquired&&cleanupConfirmed)CloudBackupLease.release(lease);try{history=CloudAudioVersions.read(prefs);}catch(Exception failure){error+=" Audio-version history could not be read.";}}
        String message=error.isEmpty()?"Audio ZIP saved and full provider read-back verified. No existing provider file was replaced.":entry!=null?entry.message+(!error.equals(entry.message)?" "+error:""):error;return new Result(entry,creationAttempted,verified,cleanupConfirmed,message+warning,error);
 }
    private void closeProvider(Closeable stream)throws IOException{if(stream==null)return;try{stream.close();}catch(IOException|RuntimeException failure){cleanupConfirmed=false;throw new IOException("Provider stream cleanup could not be confirmed.",failure);}}
    private static OutputStream bounded(OutputStream output,long max){return new FilterOutputStream(output){long count;public void write(int b)throws IOException{if(++count>max)throw new IOException("The complete ZIP exceeds its supported size.");out.write(b);}public void write(byte[] b,int off,int n)throws IOException{if(n>max-count)throw new IOException("The complete ZIP exceeds its supported size.");count+=n;out.write(b,off,n);}};}
 void cancel(){cancelled=true;CloudBackupProvider selected=provider;if(selected!=null)selected.cancel();}
}
